using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class CampusFinalDetails {public static string Run(){var root=GameObject.Find("Campus exterior upgrade").transform;var bench=UnityEngine.Object.FindObjectsByType<Transform>().Single(t=>t.name=="Garden bench"&&Mathf.Abs(t.position.z+17)<.1f);bench.position=new Vector3(17,0,-17);
void Trim(string name,Vector3 position,Vector3 scale,string material){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name=name;go.transform.SetParent(root,false);go.transform.position=position;go.transform.localScale=scale;UnityEngine.Object.DestroyImmediate(go.GetComponent<Collider>());go.GetComponent<Renderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/_FireSafety/CampusExterior/Materials/"+material+".mat");go.layer=30;GameObjectUtility.SetStaticEditorFlags(go,StaticEditorFlags.BatchingStatic);}
Trim("Central balcony fascia continuity",new Vector3(6.88f,3.15f,-.2f),new Vector3(.22f,.4f,.8f),"Campus warm ivory plaster");Trim("Central balcony terracotta continuity",new Vector3(7.01f,3.38f,-.2f),new Vector3(.055f,.1f,.8f),"Campus terracotta plaster");EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());return "Moved bus-side bench clear of bus and restored continuous balcony trim";}}
